ALTER TABLE "Achievement" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Achievement" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "Achievement" USING ("organizationId" = app.current_org_id()) WITH CHECK ("organizationId" = app.current_org_id());

